import{_ as d,o,c as r,a4 as e}from"./chunks/framework.BBs01uty.js";const u=JSON.parse('{"title":"术语与编号体系","description":"","frontmatter":{},"headers":[],"relativePath":"agent-cli/glossary.md","filePath":"agent-cli/glossary.md"}'),s={name:"agent-cli/glossary.md"};function n(c,t,a,g,i,l){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="术语与编号体系" tabindex="-1">术语与编号体系 <a class="header-anchor" href="#术语与编号体系" aria-label="Permalink to &quot;术语与编号体系&quot;">​</a></h1><blockquote><p>本项目文档 / 代码注释里大量出现 <code>FR-x</code> <code>AC-x</code> <code>V-x</code> <code>D-x</code> <code>lesson NN</code> 这类编号。 新人最常见的困惑是&quot;这些编号去哪查、是不是全局唯一&quot;。</p></blockquote><h2 id="_1-编号体系一览" tabindex="-1">1. 编号体系一览 <a class="header-anchor" href="#_1-编号体系一览" aria-label="Permalink to &quot;1. 编号体系一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前缀</th><th>含义</th><th>定义在哪</th><th>作用域</th></tr></thead><tbody><tr><td><strong>FR-x</strong></td><td>Functional Requirement（功能需求）</td><td>各任务的 <code>task.md</code> / 需求文档</td><td><strong>按任务隔离</strong>（006 的 FR-1 ≠ 007 的 FR-1）</td></tr><tr><td><strong>AC-x</strong></td><td>Acceptance Criterion（验收标准）</td><td>同上，<code>task.md</code> 的 AC 章节</td><td><strong>按任务隔离</strong></td></tr><tr><td><strong>V-x</strong></td><td>用户裁决（design 复核时用户拍板的修订）</td><td>各任务 <code>design.md</code> 的「设计复核裁决」</td><td><strong>按任务隔离</strong>，且<strong>口径优先于 design 正文</strong></td></tr><tr><td><strong>D-x</strong></td><td>Design Decision（设计决策）</td><td>需求 / 设计文档的 Decision Log</td><td>按文档隔离（005 的 D1–D38、007 的 D1–D23）</td></tr><tr><td><strong>lesson NN</strong></td><td>经验教训（跨任务沉淀）</td><td><code>knowledge/lessons/</code></td><td><strong>全局唯一</strong>，永久</td></tr><tr><td><strong>S/C/W/I/N-x</strong></td><td>审查发现编号（Security-Critical / Critical / Warning / Info / New）</td><td><code>.harness/workspace/&lt;task&gt;/review-report.md</code></td><td>按审查轮次</td></tr></tbody></table><p>⚠️ <strong>引用编号时务必带任务号</strong>（如&quot;007 的 V-5&quot;）—— 不同任务的 V-1 含义完全不同。</p><h2 id="_2-高频引用的约束与裁决-按含义速查" tabindex="-1">2. 高频引用的约束与裁决（按含义速查） <a class="header-anchor" href="#_2-高频引用的约束与裁决-按含义速查" aria-label="Permalink to &quot;2. 高频引用的约束与裁决（按含义速查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>含义</th><th>常见引用</th><th>一句话</th></tr></thead><tbody><tr><td><strong>前缀稳定性</strong></td><td><code>D23</code>（005 需求）、008 的 AC-59</td><td>Ollama 前缀 KV 缓存 44×，system prompt 前部不可改写；易变内容只作消息追加</td></tr><tr><td><strong>浮层高度恒定</strong></td><td>006 的 <code>V-5</code>、lesson 022</td><td>浮层高度生命周期内冻结；变了就整区重建（最脆弱路径）</td></tr><tr><td><strong>布局双量模型</strong></td><td>008 的 <code>V-7</code></td><td><code>contentRowsFor</code> / <code>reservedRowsFor</code> 是行数唯一公式，禁止内联算术</td></tr><tr><td><strong><code>--yes</code> 不覆盖 forced</strong></td><td>008 的 <code>V-1</code></td><td>危险命令必须人工确认，自动接受只管普通询问</td></tr><tr><td><strong>后台任务不计 busy</strong></td><td>008 的 <code>V-4</code></td><td><code>Ctrl+C</code> 的语义不被后台任务干扰</td></tr><tr><td><strong>交互唯一分派路径</strong></td><td>008 的 <code>AC-27</code></td><td>UI 审批与 LLM <code>ask_user</code> 同一套交互原语</td></tr><tr><td><strong>definitions 基线</strong></td><td>008 的 <code>AC-41</code></td><td>工具 schema 与重构前快照比对（防破坏前缀缓存）</td></tr><tr><td><strong>tick 预算</strong></td><td>006 的 <code>AC-65</code></td><td>单 tick 重绘 ≤3 行、无清屏、无 DECSTBM 重建</td></tr><tr><td><strong>forced 先于授权</strong></td><td>008 设计不变式 <code>I-3</code></td><td><code>ask &amp;&amp; forced</code> 在一切授权前短路</td></tr><tr><td><strong>非交互拒绝后台任务</strong></td><td>008 的 <code>V-8</code></td><td>单轮模式起后台任务 = 留孤儿</td></tr></tbody></table><h2 id="_3-lessons-速查-knowledge-lessons" tabindex="-1">3. Lessons 速查（<code>knowledge/lessons/</code>） <a class="header-anchor" href="#_3-lessons-速查-knowledge-lessons" aria-label="Permalink to &quot;3. Lessons 速查（`knowledge/lessons/`）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>一句话</th></tr></thead><tbody><tr><td>001</td><td>索引化记忆 + 按需加载（别把记忆全量塞 system prompt）</td></tr><tr><td>002</td><td>对话式完成工作流阶段后，需补编排层状态</td></tr><tr><td>003</td><td>任务目录命名规范（<code>workspace/{task-id}</code>）</td></tr><tr><td>004</td><td>用户输入 → 文件名的安全映射（防路径穿越）</td></tr><tr><td>005</td><td>verify 捕获的日志需禁用 ANSI 颜色</td></tr><tr><td>006</td><td>工作流 sections 校验是精确标题匹配</td></tr><tr><td>007</td><td>e2e 的&quot;输入建模&quot;必须与生产输入逐字段一致</td></tr><tr><td>008</td><td>修复引入新代码时，安全边界必须复用既有校验函数</td></tr><tr><td>009</td><td>循环必须把&quot;结束了但没产出&quot;当成一等事件上报</td></tr><tr><td>010</td><td>长诊断文本必须折行渲染；断言屏幕文本按&quot;整屏拼接&quot;匹配</td></tr><tr><td>011</td><td>注入式 mock 会掩盖集成缺陷；真实环境测试不可省</td></tr><tr><td>012</td><td>阈值与计数类逻辑要统一单位，行数统计必须认所有行尾</td></tr><tr><td>013</td><td>平台能力&quot;能不能调整&quot;必须实测，不能按文档假设</td></tr><tr><td>014</td><td>独立审查能抓到实现者与测试者结构性看不见的缺陷</td></tr><tr><td>015</td><td>需求阶段先实测本地推理引擎的隐式能力，再设计缓存方案</td></tr><tr><td>016</td><td>参考云端 CLI 时，显式区分「可迁移机制」与「平台特有约束」</td></tr><tr><td>017</td><td>测试&quot;全绿&quot;不等于真实路径可用（断言锁了格式却没锁行为）</td></tr><tr><td>018</td><td>子进程用 <code>close</code> 结算会让超时形同虚设；&quot;退出 ≠ 资源已释放&quot;</td></tr><tr><td>019</td><td>对抗性 / 边界性声明没有实测证据就不许写</td></tr><tr><td>020</td><td>修一个路径的缺陷时，必须同时检查同族路径；返工后派定点复审</td></tr><tr><td>021</td><td>写 AC 要区分「机制可验」与「端到端可验」，否则造出假 NOT-RUN</td></tr><tr><td>022</td><td>动态布局的固有代价 —— 缓解规则是&quot;浮层高度生命周期恒定&quot;</td></tr><tr><td>023</td><td>把&quot;按推荐拟定的默认项&quot;显式列出交用户复核，是高产的需求采集动作</td></tr><tr><td>024</td><td>参考主流 CLI 必须取官方文档口径（二手总结会漏关键细节）</td></tr></tbody></table><h2 id="_4-技术缩写" tabindex="-1">4. 技术缩写 <a class="header-anchor" href="#_4-技术缩写" aria-label="Permalink to &quot;4. 技术缩写&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>全称 / 含义</th></tr></thead><tbody><tr><td><strong>DECSTBM</strong></td><td><code>ESC[top;bottom r</code>，设置终端滚动区域（&quot;Mechanism&quot; 的缩写名）</td></tr><tr><td><strong>CSI / SGR / OSC</strong></td><td>ANSI 转义序列三类：<code>ESC[</code> 控制序列 / <code>ESC[…m</code> 样式 / <code>ESC]</code> 操作系统命令（如 OSC 52 写剪贴板）</td></tr><tr><td><strong>Alt Screen</strong></td><td>备用屏（<code>ESC?1049h/l</code>）：TUI 退出后原样恢复用户终端</td></tr><tr><td><strong>wrap-pending</strong></td><td>写到行末最后一列后终端进入的&quot;待换行&quot;状态（下次写才真正换行/滚动）</td></tr><tr><td><strong>pgid</strong></td><td>进程组 id。<code>detached: true</code> 使 <code>sh</code> 成组长（pgid === pid），<code>kill(-pgid)</code> 整组回收</td></tr><tr><td><strong>KV cache（前缀缓存）</strong></td><td>Ollama 对相同前缀的 prompt 复用 KV 计算（实测 44×），是前缀稳定性约束的动机</td></tr><tr><td><strong>TUI / TermSim</strong></td><td>Terminal UI / 本项目自研的 ANSI 终端模拟器（[<code>testing/term-sim.ts</code>）</td></tr><tr><td><strong>workspace-id</strong></td><td>cwd 的 sha256 前 16 位，会话按它隔离目录</td></tr><tr><td><strong>harness</strong></td><td><a href="https://github.com/jun2333/dev-agent-harness" target="_blank" rel="noreferrer"><code>DevAgent Harness</code></a> 工作流引擎，经 git submodule（<code>.harness/</code>）接入；阶段 = precondition → designing → task-planning → implementing → testing → reviewing → reflecting → git-operations</td></tr><tr><td><strong>verify 通道</strong></td><td><code>.harness/tools/verify.js</code>：按 <code>knowledge/verify.config.json</code> 执行 build+test 并落盘证据，阶段 gate 只认它</td></tr></tbody></table>',11)])])}const m=d(s,[["render",n]]);export{u as __pageData,m as default};
